import React from 'react'
import { Select, Typography } from 'antd'
import { format } from 'date-fns'
import numberFieldLengthValidationRules from '../../../CommonComponents/AmountFieldValidator'

const { Text } = Typography

const { Option } = Select

export const getPlansAndTsiData = (plansAndBenefitsData) => {
  if (!(plansAndBenefitsData && plansAndBenefitsData.benefit_groups)) return {}
  const plansData = {}
  const benefitGroupSlug = {}
  for (const benefitGroup of plansAndBenefitsData.benefit_groups) {
    plansData[benefitGroup.name] = []
    for (const plan of benefitGroup.plans) {
      const planData = { name: plan.name, 'Yearly Limit': plan.yearly_limit, id: plan.id }
      for (const benefit of plan.benefits) {
        planData[benefit.name] = benefit.tsi
      }
      plansData[benefitGroup.name].push(planData)
    }
    benefitGroupSlug[benefitGroup.name] = benefitGroup.slug
  }
  return { plansData, benefitGroupSlug }
}

export const planMapperColumns = (benefitGroups = {}, form, benefitGroupSlug) => {
  const initialColumns = [
    {
      title: 'Plan In Participant Excel',
      dataIndex: 'planIdentifier'
    }
  ]
  for (const [benefitGroup, plans] of Object.entries(benefitGroups)) {
    initialColumns.push({
      title: `${benefitGroup} Plan`,
      render: (rowData) => (
        form.getFieldDecorator(`plan_mappings._${rowData.planIdentifier}.${benefitGroupSlug[benefitGroup]}`)(
          <Select allowClear>
            {plans.map(plan => <Option key={plan.name} value={plan.id}>{plan.name}</Option>)}
          </Select>
        )
      )
    })
  }
  return initialColumns
}

export const employeeMapperColumns = ({
  plansData: benefitGroups,
  benefitGroupSlug,
  noPlanEmployeeIds,
  productId,
  getFieldDecorator,
  showError
}) => {
  benefitGroupSlug = benefitGroupSlug || {}
  const initialColumns = [
    {
      title: 'Employee/Dependent Name',
      dataIndex: 'name',
      render: (name, employeeData) => (
        <div>
          <div>{name}</div>
          {
            productId && noPlanEmployeeIds.includes(String(employeeData.id)) && (
              <div>
                <Text disabled>Atleast 1 plan is required</Text>
              </div>
            )
          }
        </div>
      )
    },
    {
      title: 'Relation',
      dataIndex: 'relationship'
    },
    {
      title: 'Gender',
      dataIndex: 'gender'
    },
    {
      title: 'Date of Birth',
      dataIndex: 'dob',
      render: dob => dob && format(dob, 'DD-MM-YYYY')
    }
  ]

  for (const [benefitGroup, plans] of Object.entries(benefitGroups)) {
    initialColumns.push({
      title: `${benefitGroup} Plan`,
      render: (rowData) => (
        getFieldDecorator(`participant_plan_mappings.${rowData.id}.${benefitGroupSlug[benefitGroup]}`)(
          <Select allowClear>
            {plans.map(plan => <Option key={plan.name} value={plan.id}>{plan.name}</Option>)}
          </Select>
        )
      )
    })
  }
  return initialColumns
}

