export const amountValidationRules = [
  {
    required: true,
    message: 'Amount is required'
  },
  {
    pattern: /^-{0,1}\d+(\.\d+)*(,\d+){0,1}$/,
    message: 'Invalid format. Allowed format is 5.000.500'
  },
  ...numberFieldLengthValidationRules
]

export const getSelectedUsersAndDependentsList = (selectedUsers) => {
  let usersWithDependents = []
  for (const user of selectedUsers) {
    usersWithDependents.push(user)
    if (Array.isArray(user.dependents) && user.dependents.length) {
      usersWithDependents = [...usersWithDependents, ...user.dependents]
    }
  }
  return usersWithDependents
}
